exercises.reference:
def can_backfill(now, free, head_need, running, cand_need, cand_hours):
    if cand_need > free:
        return False
    avail, shadow = free, None
    for end, servers in sorted(running):
        avail += servers
        if avail >= head_need:
            shadow = end
            break
    if shadow is None:
        return False
    spare = avail - head_need
    return now + cand_hours <= shadow or cand_need <= spare

